<?php
declare(strict_types=1);
require_once __DIR__.'/../devis/includes/module_bootstrap.php';
require_once __DIR__.'/../model/Client.php';

if(!devis_module_has_access('acces_liste_client'))AccessManager::denyAccess('acces_liste_client','clients/details.php');
$pdo=Database::getConnection();$id=(int)($_GET['id']??0);$client=(new Client($pdo))->getClientById($id);if(!$client){http_response_code(404);exit('Client introuvable.');}
$money=static fn(float $value):string=>number_format($value,0,',',' ').' FCFA';
$projects=$pdo->prepare('SELECT c.code,c.titre,c.date_creation,c.archived_at,COALESCE(c.montant_devis,d.total_ttc,c.cout_total_chantier,0) amount FROM chantier_banamur c LEFT JOIN devis_banamur d ON d.id=c.devis_id WHERE c.client_id=:id ORDER BY c.id DESC');$projects->execute(['id'=>$id]);$projects=$projects->fetchAll(PDO::FETCH_ASSOC)?:[];
$quotes=$pdo->prepare('SELECT numero_devis,date_emission,total_ttc,validation_generale FROM devis_banamur WHERE client_id=:id ORDER BY id DESC');$quotes->execute(['id'=>$id]);$quotes=$quotes->fetchAll(PDO::FETCH_ASSOC)?:[];
$invoices=[];try{$invoiceStatement=$pdo->prepare("SELECT fv.reference_interne,fv.fne_invoice_number,fv.invoice_date,fv.total_ttc,fv.collected_amount,fv.paiement_statut,c.code chantier_code FROM facture_vente_banamur fv LEFT JOIN chantier_banamur c ON c.id=fv.chantier_id WHERE fv.client_id=:direct_id OR c.client_id=:project_id ORDER BY COALESCE(fv.invoice_date,DATE(fv.created_at)) DESC");$invoiceStatement->execute(['direct_id'=>$id,'project_id'=>$id]);$invoices=$invoiceStatement->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $ignored){}
$invoiced=array_reduce($invoices,static fn(float $sum,array $row):float=>$sum+(float)$row['total_ttc'],0.0);$collected=array_reduce($invoices,static fn(float $sum,array $row):float=>$sum+($row['paiement_statut']==='payee'?((float)$row['collected_amount']>0?(float)$row['collected_amount']:(float)$row['total_ttc']):0),0.0);$outstanding=max(0,$invoiced-$collected);$collectionRate=$invoiced>0?round(($collected/$invoiced)*100,1):0;
$modules=$devisModuleController->modules();$devisModuleNav=$modules;$activeDevisModule='clients';$moduleTitle='Détails client';$moduleSubtitle='Vue consolidée des interactions commerciales, financières et opérationnelles.';$root=static fn(string $path):string=>devis_module_root_url($path);ob_start(); ?>
<style>
