<section class="cd-detail-head"><div><h2><?=htmlspecialchars((string)$client['nom_client'],ENT_QUOTES,'UTF-8')?></h2><p>Identifiant <?=htmlspecialchars((string)(ClientBusinessPolicy::displayIdentifier($client)['value']?:'Non renseigné'),ENT_QUOTES,'UTF-8')?> · <?=htmlspecialchars((string)($client['telephone_client']??'Téléphone non renseigné'),ENT_QUOTES,'UTF-8')?></p></div><div class="cd-detail-actions"><a href="<?=$root('clients/liste.php')?>"><i class="fa-solid fa-arrow-left"></i> Retour</a><a href="<?=$root('clients/modifier.php?id='.$id)?>"><i class="fa-solid fa-pen"></i> Ouvrir la fiche</a></div></section>
<section class="cd-summary"><article><span>CA facturé</span><strong><?=$money($invoiced)?></strong></article><article><span>Encaissé</span><strong><?=$money($collected)?></strong></article><article><span>Encours global</span><strong><?=$money($outstanding)?></strong></article><article><span>Taux d’encaissement</span><strong><?=$collectionRate?> %</strong></article></section>
<section class="cd-panel"><div class="cd-panel-head"><h3>Identité et informations fiscales</h3><span>Contrôles selon le pays fiscal</span></div><div class="cd-panel-wrap"><table><tbody><?php foreach(['client_type'=>'Type de client','fiscal_country'=>'Pays fiscal','identity_method'=>'Méthode','identity_status'=>'Statut identité','registration_type'=>'Type d’identifiant','registration_number'=>'Immatriculation','siret'=>'SIRET','siren'=>'SIREN','vat_number'=>'TVA','vat_status'=>'Contrôle TVA','identity_evidence'=>'Justificatif','identity_checked_at'=>'Dernier contrôle','ncc'=>'NCC','nom_client'=>'Raison sociale','activity_start_date'=>'Date début d’activité','fiscal_activity_label'=>'Statut d’activité (FNE)','activity_description'=>'Activité (saisie interne)','vat_liability_status'=>'Assujettissement TVA (saisie interne)','vat_last_period'=>'Dernière déclaration TVA (saisie interne)'] as $key=>$label):?><tr><th><?=htmlspecialchars($label,ENT_QUOTES,'UTF-8')?></th><td><?=htmlspecialchars((string)($client[$key]??'Non renseigné'),ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="cd-panel"><div class="cd-panel-head"><h3>Factures attachées au client</h3><span><?=count($invoices)?> facture(s)</span></div><div class="cd-panel-wrap"><table><thead><tr><th>Référence</th><th>Date</th><th>Chantier</th><th>Montant TTC</th><th>Statut</th></tr></thead><tbody><?php foreach($invoices as $invoice):?><tr><td><strong><?=htmlspecialchars((string)($invoice['fne_invoice_number']?:$invoice['reference_interne']?:'Sans référence'),ENT_QUOTES,'UTF-8')?></strong></td><td><?=htmlspecialchars((string)($invoice['invoice_date']??'Non renseignée'),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars((string)($invoice['chantier_code']??'Hors chantier'),ENT_QUOTES,'UTF-8')?></td><td><strong><?=$money((float)$invoice['total_ttc'])?></strong></td><td><span class="cd-status"><?=htmlspecialchars((string)$invoice['paiement_statut'],ENT_QUOTES,'UTF-8')?></span></td></tr><?php endforeach;?><?php if(!$invoices):?><tr><td colspan="5" class="cd-empty">Aucune facture attachée à ce client.</td></tr><?php endif;?></tbody></table></div></section>
<section class="cd-panel"><div class="cd-panel-head"><h3>Devis et chantiers</h3><span><?=count($quotes)?> devis · <?=count($projects)?> chantier(s)</span></div><div class="cd-panel-wrap"><table><thead><tr><th>Type</th><th>Référence</th><th>Date</th><th>Montant</th><th>État</th></tr></thead><tbody><?php foreach($quotes as $quote):?><tr><td>Devis</td><td><?=htmlspecialchars((string)$quote['numero_devis'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars((string)$quote['date_emission'],ENT_QUOTES,'UTF-8')?></td><td><?=$money((float)$quote['total_ttc'])?></td><td><?=htmlspecialchars((string)$quote['validation_generale'],ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?><?php foreach($projects as $project):?><tr><td>Chantier</td><td><strong><?=htmlspecialchars((string)$project['code'],ENT_QUOTES,'UTF-8')?></strong><span class="cd-muted"><?=htmlspecialchars((string)$project['titre'],ENT_QUOTES,'UTF-8')?></span></td><td><?=htmlspecialchars((string)$project['date_creation'],ENT_QUOTES,'UTF-8')?></td><td><?=$money((float)$project['amount'])?></td><td><?=empty($project['archived_at'])?'Actif':'Archivé'?></td></tr><?php endforeach;?><?php if(!$quotes&&!$projects):?><tr><td colspan="5" class="cd-empty">Aucune activité commerciale ou opérationnelle.</td></tr><?php endif;?></tbody></table></div></section>
